// 工具回执正文的取料面（2026-10-23 实测缺陷的修法）。
//
// 类型上 `ToolResult.output: string` 是必填，但那只约束**我们自己的**工具：插件工具、MCP 工具、
// 脚本化工具都是运行期才拿到的，返回 `{ok:true}`（缺 output）/ `output:null` / `output:{…}`
// 都完全可能（`tools/base.ts` 的接口管不到跨进程边界）。旧实现在取料处直接 `.slice` 与字符串拼接
// ⇒ ① `TypeError: Cannot read properties of undefined (reading 'slice')` 把整轮任务打死；
// ② 修掉崩溃后落盘的是字面量 `"undefined"` 或用 `+` 拼出的 `"[object Object]"`——
// 一条"有回执但读不懂"的 tool_result，比明说"这条回执没有正文"更坏。
//
// 本模块给**唯一**一份口径：正常字符串逐字返回（不许为了安全全包一层），
// 真空串原样保留（空串是"真的没输出"这一事实），畸形给出彼此分得开的可读替代串。

/** 循环引用安全的 JSON 摘要（**不许抛**：参数/结果里有环时 JSON.stringify 直接抛 TypeError）。
 *  环处换成显式占位（与脱敏面同一口径："[循环引用]"），既不炸也不静默丢字段。 */
export function safeJsonSummary(value: unknown, seen: WeakSet<object> = new WeakSet()): string {
  try {
    return JSON.stringify(value, (_key, v: unknown) => {
      if (typeof v === "object" && v !== null) {
        if (seen.has(v)) return "[循环引用]";
        seen.add(v);
      }
      return v;
    }) ?? "";
  } catch {
    // 兜底：带 getter 的对象、Proxy 陷阱等 stringify 也可能抛——摘要面不许因此炸掉整轮。
    return "[无法序列化]";
  }
}

/** 工具回执正文归一化（`unknown` 进、`string` 出，**永不抛**）。
 *
 *  各分支的区分是判据而不是装饰：`stuck.ts#stuckObservationOf` 拿这串做卡死比较，
 *  "缺失"与"null"若折成同一串，不返回正文的工具会被判成"卡在同一动作"。
 *  返回的替代串都明说"没有正文"，模型不会把它误读成工具的真实输出。 */
export function toolOutputText(output: unknown): string {
  if (typeof output === "string") return output; // 正常路径：逐字不变（含真空串）
  if (output === undefined) return "[工具回执缺少 output：这条回执没有正文]";
  if (output === null) return "[工具回执 output 为 null：这条回执没有正文]";
  // 对象/数组/数字/布尔等：序列化出来，而不是 String(...)（那会得到 "[object Object]"）。
  const json = safeJsonSummary(output);
  if (json !== "") return json;
  // JSON.stringify 对 function / symbol / undefined 返回 undefined ⇒ 这里拿不到可读正文。
  return "[工具回执 output 无法序列化：这条回执没有正文]";
}

